function normalizeHeader(key: string) {
  return key.toLowerCase().replace(/[\s_\-./()]/g, "").trim();
}

function sourceFieldKey(key: string) {
  const normalized = normalizeHeader(key);
  return Object.entries(SOURCE_FIELD_ALIASES).find(([, aliases]) => aliases.includes(normalized))?.[0];
}

function sourceFieldLabel(key: string, lang: string) {
  const label = SOURCE_FIELD_LABELS[sourceFieldKey(key) || ""];
  return label?.[lang as "ar" | "he" | "en"] || label?.en || key;
}

function sourceFieldRank(key: string) {
  const order = ["project", "unit", "statusCode", "status", "building", "floor", "view", "totalArea", "usableArea", "gardenShare", "price", "companyCode", "phone", "clientSource", "interest", "budget", "firstContact", "lastFollowUp", "nextFollowUp", "notes"];
  const index = order.indexOf(sourceFieldKey(key) || "");
  return index === -1 ? 99 : index;
}

function attributesFromJson(raw: unknown): Record<string, string> {
  if (!raw || typeof raw !== "string") return {};
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    return Object.fromEntries(Object.entries(parsed).map(([key, value]) => [key, value == null ? "" : String(value)]));
  } catch {
    return {};
  }
}

function sourceOwner(item: any) {
  if (item.ownerName) return String(item.ownerName);
  const attributes = attributesFromJson(item.attributesJson);
  const entry = Object.entries(attributes).find(([key]) => OWNER_HEADERS.has(normalizeHeader(key)));
  return entry?.[1] || "—";
}

function money(value: unknown) {
  return `${Number(value ?? 0).toLocaleString()} EGP`;
}

function numberValue(value: string) {
  return Math.max(0, Math.round(Number(value) || 0));
}

function statusClass(status: string) {
  return status === "sold" ? "border-rose-300/25 bg-rose-300/10 text-rose-100" : status === "reserved" ? "border-amber-300/25 bg-amber-300/10 text-amber-100" : status === "inactive" ? "border-white/15 bg-white/5 text-white/50" : "border-emerald-300/25 bg-emerald-300/10 text-emerald-100";
}

function statusText(status: string, t: any) {
  return status === "sold" ? t.sold : status === "reserved" ? t.reserved : status === "inactive" ? t.inactive : t.available;
}

function importedStatus(item: any) {
  const attributes = attributesFromJson(item.attributesJson);
  const sourceStatus = Object.entries(attributes).find(([key]) => sourceFieldKey(key) === "statusCode")?.[1] || Object.entries(attributes).find(([key]) => sourceFieldKey(key) === "status")?.[1] || "";
  const normalized = sourceStatus.toLowerCase();
  if (["unsold", "available", "vacant", "متاح", "غير مباع", "זמין"].some(term => normalized.includes(term))) return "available";
  if (["sold", "completed", "مباع", "נמכר"].some(term => normalized.includes(term))) return "sold";
  if (["reserved", "contracted", "hold", "محجوز", "متعاقد", "שמור"].some(term => normalized.includes(term))) return "reserved";
  if (["inactive", "cancelled", "غير نشط", "לא פעיל"].some(term => normalized.includes(term))) return "inactive";
  return item.status;
}

function useSalesCenter() {
  const result = trpc.sales.center.useQuery();
  return { data: result.data ?? emptyCenter, isLoading: result.isLoading, isError: result.isError, refetch: result.refetch };
}

function useSalesViewer() {
  const result = trpc.sales.operations.useQuery({});
  return { canManage: result.data?.viewer.canManage ?? false };
}

function SalesShell({ children, title, subtitle, action }: { children: ReactNode; title: string; subtitle: string; action?: ReactNode }) {
  const { dir } = useLocale();
  const [, navigate] = useLocation();
  const { lang } = useLocale();
  const t = salesText[lang];
  const { canManage } = useSalesViewer();
  const isSalesRoot = title === t.center;
  const detailAction = subtitle === t.propertyDetails || subtitle === t.clientDetails;
  const actionClass = [
    detailAction ? "[&>button:first-child]:hidden" : "",
    subtitle === t.propertyDetails && !canManage ? "[&>button:nth-child(2)]:hidden" : "",
  ].filter(Boolean).join(" ");
  return (
    <main dir={dir} className="min-h-screen overflow-x-clip bg-[#071a27] px-4 py-7 text-white sm:px-8">
      <div className="mx-auto w-full max-w-[1550px]">
        <header className="mb-7 flex flex-col gap-4 border-b border-white/10 pb-6 sm:flex-row sm:flex-wrap sm:items-start sm:justify-between">
          <div className="min-w-0">
            <div className="mb-2 flex items-center gap-2 text-xs uppercase tracking-[.28em] text-[#d8b26b]"><Landmark className="h-4 w-4" /> DAR.EST</div>
            <h1 className="text-3xl font-semibold sm:text-5xl">{title}</h1>
            <p className="mt-2 max-w-3xl text-white/55">{subtitle}</p>
          </div>
          <div className="flex w-full flex-wrap items-center gap-2 sm:w-auto sm:justify-end">
            <LocaleSwitcher />
            {!isSalesRoot && <Button variant="outline" onClick={() => navigate("/sales")} className="border-white/15 bg-white/[.04] text-white hover:bg-white/10"><ArrowLeft className="me-2 h-4 w-4" />{t.back}</Button>}
            {action && <div data-sales-action className={actionClass}>{action}</div>}
          </div>
        </header>
        {children}
      </div>
    </main>
  );
}

function BackToSales() {
  const [, navigate] = useLocation();
  const { lang } = useLocale();
  return <Button variant="outline" onClick={() => navigate("/sales")} className="border-white/15 bg-white/[.04] text-white hover:bg-white/10"><ChevronLeft className="me-1 h-4 w-4" />{salesText[lang].back}</Button>;
}

function EmptyState({ message, icon }: { message: string; icon?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-white/15 bg-white/[.025] px-5 py-14 text-center text-white/55">{icon}<p className="mt-3">{message}</p></div>;
}

function SalesQueryFailure({ retry }: { retry: () => void | Promise<unknown> }) {
  const { lang } = useLocale();
  const copy = salesFailureCopy[lang];
  return <div role="alert" className="rounded-2xl border border-rose-300/25 bg-rose-400/[.07] px-5 py-12 text-center text-white"><PackageOpen className="mx-auto h-9 w-9 text-rose-200" /><h2 className="mt-4 text-lg font-semibold">{copy.title}</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-white/65">{copy.description}</p><Button type="button" onClick={() => { void retry(); }} className="mt-5 bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]"><RefreshCw className="me-2 h-4 w-4" />{copy.retry}</Button></div>;
}

function ImportedFields({ values, editable, onChange }: { values: Record<string, string>; editable?: boolean; onChange?: (key: string, value: string) => void }) {
  const { lang } = useLocale();
  const entries = Object.entries(values).sort(([first], [second]) => sourceFieldRank(first) - sourceFieldRank(second) || first.localeCompare(second));
  if (!entries.length) return <p className="text-sm text-white/45">—</p>;
  return <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{entries.map(([key, value]) => <div key={key} className="min-w-0 border-b border-white/10 pb-3"><p className="truncate text-xs text-[#d8b26b]" title={key}>{sourceFieldLabel(key, lang)}</p>{sourceFieldLabel(key, lang) !== key && <p className="mt-0.5 truncate text-[10px] text-white/30" title={key}>{key}</p>}{editable ? <input className={`${inputClass} mt-1 py-2`} value={value} onChange={event => onChange?.(key, event.target.value)} /> : <p className="mt-1 break-words text-sm leading-6 text-white/80">{value || "—"}</p>}</div>)}</div>;
}

export function SalesHub() {
  const { lang } = useLocale();
  const t = salesText[lang];
  const [, navigate] = useLocation();
  const { data, isLoading, isError, refetch } = useSalesCenter();
  const { canManage } = useSalesViewer();
  const integrationCard = lang === "ar" ? { title: "التكامل مع موقع آخر", description: "API وشرح ربط النماذج والعقارات" } : { title: "Website integration", description: "API and setup for listings and leads" };
  if (isError) return <SalesShell title={t.center} subtitle={t.overview}><SalesQueryFailure retry={refetch} /></SalesShell>;
  const modules = [
    { title: t.properties, description: `${data.properties.length} · ${t.details}`, icon: Building2, path: "/sales/properties" },
    { title: t.clients, description: `${data.clients.length} · ${t.details}`, icon: UsersRound, path: "/sales/clients" },
    { title: t.contracts, description: `${data.contracts.length} · ${t.installmentSchedule}`, icon: ClipboardList, path: "/sales/contracts" },
    { title: t.crm, description: t.crmDescription, icon: Target, path: "/sales/crm" },
    ...(canManage ? [{ title: integrationCard.title, description: integrationCard.description, icon: PlugZap, path: "/sales/integrations" }] : []),
    ...(canManage ? [{ title: t.imports, description: `${data.batches.length} · ${t.uploaded}`, icon: FileSpreadsheet, path: "/sales/import" }] : []),
    { title: t.team, description: t.assistant, icon: CheckCircle2, path: "/sales/team" },
  ];
  return <SalesShell title={t.center} subtitle={t.overview}>{isLoading ? <EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /> : <><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5">{modules.map(module => <button key={module.path} onClick={() => navigate(module.path)} className="group rounded-[1.4rem] border border-white/10 bg-white/[.035] p-5 text-start transition-[transform,background-color,border-color] duration-200 hover:-translate-y-0.5 hover:border-[#d8b26b]/45 hover:bg-[#0b2a3a]/70 focus:outline-none focus:ring-2 focus:ring-[#d8b26b]/60"><module.icon className="h-7 w-7 text-[#d8b26b]" /><h2 className="mt-6 text-lg font-semibold">{module.title}</h2><p className="mt-2 text-sm leading-6 text-white/55">{module.description}</p></button>)}</div><div className="mt-6 grid gap-4 lg:grid-cols-3"><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle className="text-base">{t.properties}</CardTitle></CardHeader><CardContent className="pt-0 text-3xl font-semibold text-[#e9cc87]">{data.properties.length}</CardContent></Card><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle className="text-base">{t.clients}</CardTitle></CardHeader><CardContent className="pt-0 text-3xl font-semibold text-[#e9cc87]">{data.clients.length}</CardContent></Card><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle className="text-base">{t.contracts}</CardTitle></CardHeader><CardContent className="pt-0 text-3xl font-semibold text-[#e9cc87]">{data.contracts.length}</CardContent></Card></div></>}</SalesShell>;
}

export function SalesProperties() {
  const { lang } = useLocale();
  const t = salesText[lang];
  const [, navigate] = useLocation();
  const { data, isLoading, isError, refetch } = useSalesCenter();
  const { canManage } = useSalesViewer();
  const [search, setSearch] = useState("");
  const properties = useMemo(() => data.properties.filter((item: any) => `${item.name} ${item.address || ""} ${sourceOwner(item)} ${item.status}`.toLowerCase().includes(search.trim().toLowerCase())), [data.properties, search]);
  const importAction = canManage ? <Button onClick={() => navigate("/sales/import")} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]"><FileSpreadsheet className="me-2 h-4 w-4" />{t.import}</Button> : undefined;
  if (isError) return <SalesShell title={t.properties} subtitle={t.details} action={importAction}><SalesQueryFailure retry={refetch} /></SalesShell>;
  return <SalesShell title={t.properties} subtitle={t.details} action={importAction}><div className="mb-5 flex max-w-xl items-center gap-2 rounded-xl border border-white/10 bg-black/15 px-3"><Search className="h-4 w-4 text-white/40" /><input className="w-full bg-transparent py-3 text-sm outline-none placeholder:text-white/30" placeholder={t.searchProperties} value={search} onChange={event => setSearch(event.target.value)} /></div>{isLoading ? <EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /> : !properties.length ? <EmptyState message={data.properties.length ? t.searchProperties : t.noProperties} icon={<Building2 className="mx-auto h-9 w-9 text-[#d8b26b]" />} /> : <div className="overflow-x-auto rounded-[1.45rem] border border-white/10 bg-white/[.025]"><div className="min-w-[970px]"><div className="grid grid-cols-[1.5fr_1.3fr_1fr_.8fr_.7fr_.8fr] gap-4 border-b border-white/10 px-5 py-3 text-xs uppercase tracking-[.12em] text-white/40"><span>{t.property}</span><span>{t.owner}</span><span>{t.address}</span><span>{t.area}</span><span>{t.price}</span><span>{t.status}</span></div>{properties.map((item: any) => { const status = importedStatus(item); return <button key={item.id} onClick={() => navigate(`/sales/properties/${item.id}`)} className="grid w-full grid-cols-[1.5fr_1.3fr_1fr_.8fr_.7fr_.8fr] gap-4 border-b border-white/7 px-5 py-4 text-start transition-colors hover:bg-[#d8b26b]/[.06] focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[#d8b26b]/45"><span className="min-w-0"><strong className="block truncate text-sm text-white">{item.name}</strong><small className="mt-1 block truncate text-white/40">{item.propertyType || "—"}</small></span><span className="truncate text-sm text-white/75">{sourceOwner(item)}</span><span className="truncate text-sm text-white/60">{item.address || "—"}</span><span className="text-sm text-white/70">{item.areaSqm == null ? "—" : `${item.areaSqm} m²`}</span><span className="text-sm font-medium text-[#e9cc87]">{item.listPriceIls == null ? "—" : money(item.listPriceIls)}</span><span><Badge className={statusClass(status)}>{statusText(status, t)}</Badge></span></button>; })}</div></div>}</SalesShell>;
}

export function SalesPropertyDetail() {
  const { lang } = useLocale();
  const t = salesText[lang];
  const [, params] = useRoute("/sales/properties/:id");
  const [, navigate] = useLocation();
  const { data, isLoading, isError, refetch } = useSalesCenter();
  const property = data.properties.find((item: any) => String(item.id) === String(params?.id));
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState<Record<string, string>>({});
  const [attributes, setAttributes] = useState<Record<string, string>>({});
  const [publicDraft, setPublicDraft] = useState({ description: "", images: "", paymentPlan: "", videoUrl: "", tourUrl: "", latitude: "", longitude: "" });
  const [plan, setPlan] = useState({ price: "", discountKind: "none", discount: "0", deposit: "0", frequency: "quarterly", years: "1", firstDate: "" });
  const utils = trpc.useUtils();
  const update = trpc.sales.updateProperty.useMutation({ onSuccess: () => { setEditing(false); utils.sales.center.invalidate(); } });
  const updatePublic = trpc.sales.updatePublicProperty.useMutation({ onSuccess: () => { utils.sales.center.invalidate(); } });
  const displayStatus = property ? importedStatus(property) : "available";
  useEffect(() => { if (property) { setDraft({ name: String(property.name || ""), address: String(property.address || ""), ownerName: String(property.ownerName || sourceOwner(property) || ""), propertyType: String(property.propertyType || ""), status: String(displayStatus), areaSqm: property.areaSqm == null ? "" : String(property.areaSqm), listPriceIls: property.listPriceIls == null ? "" : String(property.listPriceIls) }); setAttributes(attributesFromJson(property.attributesJson)); setPublicDraft({ description: String(property.publicDescription || ""), images: property.publicImagesJson ? (() => { try { return (JSON.parse(property.publicImagesJson) as string[]).join("\n"); } catch { return ""; } })() : "", paymentPlan: property.paymentPlanJson ? (() => { try { return String((JSON.parse(property.paymentPlanJson) as any).summary || ""); } catch { return ""; } })() : "", videoUrl: String(property.publicVideoUrl || ""), tourUrl: String(property.publicTourUrl || ""), latitude: String(property.publicLatitude || ""), longitude: String(property.publicLongitude || "") }); setPlan(current => ({ ...current, price: property.listPriceIls == null ? current.price : String(property.listPriceIls) })); } }, [property?.id, displayStatus]);
  const contracts = property ? data.contracts.filter((contract: any) => Number(contract.salesPropertyId) === Number(property.id)) : [];
  const price = numberValue(plan.price); const discount = numberValue(plan.discount); const discountAmount = plan.discountKind === "percentage" ? Math.round(price * Math.min(discount, 100) / 100) : plan.discountKind === "fixed" ? Math.min(price, discount) : 0; const net = price - discountAmount; const deposit = Math.min(net, numberValue(plan.deposit)); const balance = net - deposit; const count = balance ? (plan.frequency === "quarterly" ? 4 : plan.frequency === "semiannual" ? 2 : 1) * Math.max(1, Math.min(5, Number(plan.years) || 1)) : 0; const installment = count ? Math.floor(balance / count) : 0;
  const save = () => { if (!property || !draft.name.trim()) return; update.mutate({ id: Number(property.id), name: draft.name.trim(), address: draft.address.trim() || null, ownerName: draft.ownerName.trim() || null, propertyType: draft.propertyType.trim() || null, status: draft.status as "available" | "reserved" | "sold" | "inactive", areaSqm: draft.areaSqm.trim() ? numberValue(draft.areaSqm) : null, listPriceIls: draft.listPriceIls.trim() ? numberValue(draft.listPriceIls) : null, attributesJson: JSON.stringify(attributes) }); };
  if (isLoading) return <SalesShell title={t.propertyDetails} subtitle={t.loading}><EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /></SalesShell>;
  if (isError) return <SalesShell title={t.propertyDetails} subtitle={t.details} action={<BackToSales />}><SalesQueryFailure retry={refetch} /></SalesShell>;
  if (!property) return <SalesShell title={t.propertyDetails} subtitle={t.details} action={<BackToSales />}><EmptyState message={t.noRecord} icon={<PackageOpen className="mx-auto h-9 w-9 text-[#d8b26b]" />} /></SalesShell>;
  const isPublished = Boolean(property.isPublished);
  const savePublic = (published = isPublished) => updatePublic.mutate({ id: Number(property.id), isPublished: published, publicDescription: publicDraft.description.trim() || null, publicImagesJson: JSON.stringify(publicDraft.images.split(/\r?\n/).map(value => value.trim()).filter(Boolean)), paymentPlanJson: JSON.stringify({ summary: publicDraft.paymentPlan.trim() }), publicVideoUrl: publicDraft.videoUrl.trim() || null, publicTourUrl: publicDraft.tourUrl.trim() || null, publicLatitude: publicDraft.latitude.trim() || null, publicLongitude: publicDraft.longitude.trim() || null });
  const togglePublic = () => savePublic(!isPublished);
  return <SalesShell title={property.name} subtitle={t.propertyDetails} action={<><BackToSales /><Button variant="outline" onClick={togglePublic} disabled={updatePublic.isPending} className="border-[#d8b26b]/40 bg-white/[.04] text-[#f1d58f] hover:bg-white/10">{isPublished ? <EyeOff className="me-2 h-4 w-4" /> : <Eye className="me-2 h-4 w-4" />}{updatePublic.isPending ? t.loading : isPublished ? "إخفاء عن العملاء" : "نشر للعملاء"}</Button><Button onClick={() => editing ? save() : setEditing(true)} disabled={update.isPending} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]">{update.isPending ? t.loading : editing ? t.save : t.edit}</Button></>}><div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><div className="space-y-5"><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader className="flex-row items-center justify-between"><CardTitle>{t.basicInformation}</CardTitle><Badge className={statusClass(displayStatus)}>{statusText(displayStatus, t)}</Badge></CardHeader><CardContent className="grid gap-3 pt-0 md:grid-cols-2">{([['name', t.property], ['ownerName', t.owner], ['address', t.address], ['propertyType', t.type], ['areaSqm', t.area], ['listPriceIls', t.price]] as const).map(([key, label]) => <label key={key} className="block"><span className="mb-1 block text-xs text-white/45">{label}</span>{editing ? <input className={inputClass} type={key === 'areaSqm' || key === 'listPriceIls' ? 'number' : 'text'} value={draft[key] || ""} onChange={event => setDraft(current => ({ ...current, [key]: event.target.value }))} /> : <p className="min-h-10 rounded-xl border border-white/8 bg-black/10 px-3 py-2.5 text-sm text-white/85">{key === 'areaSqm' ? (property.areaSqm == null ? '—' : `${property.areaSqm} m²`) : key === 'listPriceIls' ? (property.listPriceIls == null ? '—' : money(property.listPriceIls)) : key === 'ownerName' ? sourceOwner(property) : property[key] || '—'}</p>}</label>)}<label className="block"><span className="mb-1 block text-xs text-white/45">{t.status}</span>{editing ? <select className={inputClass} value={draft.status || "available"} onChange={event => setDraft(current => ({ ...current, status: event.target.value }))}><option value="available">{t.available}</option><option value="reserved">{t.reserved}</option><option value="sold">{t.sold}</option><option value="inactive">{t.inactive}</option></select> : <p className="min-h-10 rounded-xl border border-white/8 bg-black/10 px-3 py-2.5 text-sm text-white/85">{statusText(displayStatus, t)}</p>}</label>{editing && <Button type="button" variant="outline" onClick={() => setEditing(false)} className="self-end border-white/15 text-white hover:bg-white/10">{t.cancel}</Button>}</CardContent></Card><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle>{t.imported}</CardTitle><p className="text-sm font-normal text-white/50">{t.allImported}</p></CardHeader><CardContent className="pt-0"><ImportedFields values={attributes} editable={editing} onChange={(key, value) => setAttributes(current => ({ ...current, [key]: value }))} /></CardContent></Card><Card className="border-[#d8b26b]/25 bg-[#0b2a3a]/55 text-white"><CardHeader><CardTitle>بيانات العرض للعملاء</CardTitle><p className="text-sm font-normal text-white/50">أضف وصفاً، وضع رابط كل صورة في سطر مستقل، ثم احفظ البيانات.</p></CardHeader><CardContent className="space-y-3 pt-0"><textarea className={inputClass + " min-h-24 resize-y"} placeholder="وصف العقار ومميزاته" value={publicDraft.description} onChange={event => setPublicDraft(current => ({ ...current, description: event.target.value }))} /><textarea className={inputClass + " min-h-20 resize-y"} placeholder={"رابط صورة 1\nرابط صورة 2"} value={publicDraft.images} onChange={event => setPublicDraft(current => ({ ...current, images: event.target.value }))} /><textarea className={inputClass + " min-h-20 resize-y"} placeholder="مثال: مقدم 10% وتقسيط حتى 5 سنوات" value={publicDraft.paymentPlan} onChange={event => setPublicDraft(current => ({ ...current, paymentPlan: event.target.value }))} /><div className="grid gap-3 md:grid-cols-2"><input className={inputClass} type="url" placeholder="رابط فيديو الوحدة (YouTube أو MP4)" value={publicDraft.videoUrl} onChange={event => setPublicDraft(current => ({ ...current, videoUrl: event.target.value }))} /><input className={inputClass} type="url" placeholder="رابط الجولة الافتراضية" value={publicDraft.tourUrl} onChange={event => setPublicDraft(current => ({ ...current, tourUrl: event.target.value }))} /></div><div className="grid gap-3 md:grid-cols-2"><input className={inputClass} inputMode="decimal" placeholder="خط العرض Latitude" value={publicDraft.latitude} onChange={event => setPublicDraft(current => ({ ...current, latitude: event.target.value }))} /><input className={inputClass} inputMode="decimal" placeholder="خط الطول Longitude" value={publicDraft.longitude} onChange={event => setPublicDraft(current => ({ ...current, longitude: event.target.value }))} /></div><p className="text-xs leading-6 text-white/45">يمكن ترك الإحداثيات فارغة لاستخدام موقع Porto Golf التقريبي. لا تضع بيانات داخلية أو روابط غير مخصصة للنشر.</p><Button type="button" onClick={() => savePublic()} disabled={updatePublic.isPending} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]">{updatePublic.isPending ? t.loading : "حفظ بيانات العرض"}</Button></CardContent></Card><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle>{t.linkedContracts}</CardTitle></CardHeader><CardContent className="pt-0">{contracts.length ? <div className="space-y-2">{contracts.map((contract: any) => <button key={contract.id} onClick={() => navigate(`/sales/contracts#contract-${contract.id}`)} className="flex w-full items-center justify-between rounded-xl border border-white/10 bg-black/10 px-3 py-3 text-start hover:bg-white/[.06]"><span><strong>{contract.contractNumber}</strong><small className="ms-2 text-white/45">{contract.status}</small></span><span className="text-[#e9cc87]">{money(contract.netPriceIls)}</span></button>)}</div> : <p className="text-sm text-white/45">—</p>}</CardContent></Card></div><PaymentPlanCalculator t={t} plan={plan} setPlan={setPlan} price={price} net={net} deposit={deposit} balance={balance} count={count} installment={installment} /></div></SalesShell>;
}

function PaymentPlanCalculator({ t, plan, setPlan, price, net, deposit, balance, count, installment }: { t: any; plan: any; setPlan: any; price: number; net: number; deposit: number; balance: number; count: number; installment: number }) {
  const update = (key: string, value: string) => setPlan((current: any) => ({ ...current, [key]: value }));
  return <Card className="h-fit border-[#d8b26b]/25 bg-[#0b2a3a]/55 text-white"><CardHeader><CardTitle>{t.paymentPlan}</CardTitle><p className="text-sm font-normal text-white/50">{t.paymentPreview}</p></CardHeader><CardContent className="space-y-3 pt-0"><label><span className="mb-1 block text-xs text-white/45">{t.price}</span><input className={inputClass} type="number" min="0" value={plan.price} onChange={event => update('price', event.target.value)} /></label><div className="grid grid-cols-2 gap-2"><label><span className="mb-1 block text-xs text-white/45">{t.discount}</span><select className={inputClass} value={plan.discountKind} onChange={event => update('discountKind', event.target.value)}><option value="none">—</option><option value="fixed">EGP</option><option value="percentage">%</option></select></label><label><span className="mb-1 block text-xs text-white/45">{t.discount}</span><input className={inputClass} type="number" min="0" value={plan.discount} onChange={event => update('discount', event.target.value)} /></label></div><label><span className="mb-1 block text-xs text-white/45">{t.deposit}</span><input className={inputClass} type="number" min="0" value={plan.deposit} onChange={event => update('deposit', event.target.value)} /></label><div className="grid grid-cols-2 gap-2"><label><span className="mb-1 block text-xs text-white/45">{t.frequency}</span><select className={inputClass} value={plan.frequency} onChange={event => update('frequency', event.target.value)}><option value="quarterly">{t.quarterly}</option><option value="semiannual">{t.semiannual}</option><option value="annual">{t.annual}</option></select></label><label><span className="mb-1 block text-xs text-white/45">{t.term}</span><select className={inputClass} value={plan.years} onChange={event => update('years', event.target.value)}>{[1, 2, 3, 4, 5].map(year => <option key={year} value={year}>{year} {t.years}</option>)}</select></label></div><div className="grid gap-2 border-t border-white/10 pt-4 text-sm"><p className="flex justify-between"><span className="text-white/50">{t.netPrice}</span><strong>{money(net)}</strong></p><p className="flex justify-between"><span className="text-white/50">{t.deposit}</span><strong>{money(deposit)}</strong></p><p className="flex justify-between"><span className="text-white/50">{t.balance}</span><strong>{money(balance)}</strong></p><p className="flex justify-between text-[#e9cc87]"><span>{t.installments} ({count})</span><strong>{money(installment)}</strong></p></div></CardContent></Card>;
}

export function SalesClients() {
  const { lang } = useLocale(); const t = salesText[lang]; const [, navigate] = useLocation(); const { data, isLoading, isError, refetch } = useSalesCenter(); const [search, setSearch] = useState("");
  const { canManage } = useSalesViewer();
  const clients = useMemo(() => data.clients.filter((item: any) => `${item.name} ${item.email || ""} ${item.phone || ""} ${item.identityNumber || ""}`.toLowerCase().includes(search.trim().toLowerCase())), [data.clients, search]);
  if (isError) return <SalesShell title={t.clients} subtitle={t.details}><SalesQueryFailure retry={refetch} /></SalesShell>;
  const importAction = canManage ? <Button onClick={() => navigate("/sales/import")} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]"><FileSpreadsheet className="me-2 h-4 w-4" />{t.import}</Button> : undefined;
  return <SalesShell title={t.clients} subtitle={t.details} action={importAction}><div className="mb-5 flex max-w-xl items-center gap-2 rounded-xl border border-white/10 bg-black/15 px-3"><Search className="h-4 w-4 text-white/40" /><input className="w-full bg-transparent py-3 text-sm outline-none placeholder:text-white/30" placeholder={t.searchClients} value={search} onChange={event => setSearch(event.target.value)} /></div>{isLoading ? <EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /> : !clients.length ? <EmptyState message={data.clients.length ? t.searchClients : t.noClients} icon={<UsersRound className="mx-auto h-9 w-9 text-[#d8b26b]" />} /> : <div className="overflow-x-auto rounded-[1.45rem] border border-white/10 bg-white/[.025]"><div className="min-w-[850px]"><div className="grid grid-cols-[1.4fr_1.3fr_1.1fr_1.1fr_.8fr] gap-4 border-b border-white/10 px-5 py-3 text-xs uppercase tracking-[.12em] text-white/40"><span>{t.client}</span><span>Email</span><span>Phone</span><span>ID</span><span>{t.linkedContracts}</span></div>{clients.map((item: any) => { const total = data.contracts.filter((contract: any) => Number(contract.salesClientId) === Number(item.id)).length; return <button key={item.id} onClick={() => navigate(`/sales/clients/${item.id}`)} className="grid w-full grid-cols-[1.4fr_1.3fr_1.1fr_1.1fr_.8fr] gap-4 border-b border-white/7 px-5 py-4 text-start transition-colors hover:bg-[#d8b26b]/[.06] focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[#d8b26b]/45"><span className="truncate text-sm font-semibold text-white">{item.name}</span><span className="truncate text-sm text-white/60">{item.email || "—"}</span><span className="truncate text-sm text-white/70">{item.phone || "—"}</span><span className="truncate text-sm text-white/60">{item.identityNumber || "—"}</span><span className="text-sm text-[#e9cc87]">{total}</span></button>; })}</div></div>}</SalesShell>;
}

export function SalesClientDetail() {
  const { lang } = useLocale(); const t = salesText[lang]; const callT = callInventoryCopy[lang]; const [, params] = useRoute("/sales/clients/:id"); const [, navigate] = useLocation(); const { data, isLoading, isError, refetch } = useSalesCenter(); const { canManage } = useSalesViewer(); const client = data.clients.find((item: any) => String(item.id) === String(params?.id)); const clientId = Number(client?.id || 0); const [editing, setEditing] = useState(false); const [draft, setDraft] = useState<Record<string, string>>({}); const [attributes, setAttributes] = useState<Record<string, string>>({}); const [callOpen, setCallOpen] = useState(false); const [callDraft, setCallDraft] = useState({ callType: "outbound" as const, outcome: "", interestLevel: "medium" as const, interestSubject: "", nextCallAt: "", notes: "" }); const utils = trpc.useUtils(); const inventory = trpc.sales.listCallInventory.useQuery({ salesClientId: clientId }, { enabled: Boolean(clientId) }); const update = trpc.sales.updateClient.useMutation({ onSuccess: () => { setEditing(false); utils.sales.center.invalidate(); } }); const createCall = trpc.sales.createCallInventory.useMutation({ onSuccess: () => { setCallOpen(false); setCallDraft({ callType: "outbound", outcome: "", interestLevel: "medium", interestSubject: "", nextCallAt: "", notes: "" }); utils.sales.listCallInventory.invalidate({ salesClientId: clientId }); } });
  useEffect(() => { if (client) { setDraft({ name: String(client.name || ""), email: String(client.email || ""), phone: String(client.phone || ""), identityNumber: String(client.identityNumber || "") }); setAttributes(attributesFromJson(client.attributesJson)); } }, [client?.id]);
  const contracts = client ? data.contracts.filter((contract: any) => Number(contract.salesClientId) === Number(client.id)) : []; const logs = inventory.data ?? [];
  const save = () => { if (!client || !draft.name.trim()) return; update.mutate({ id: clientId, name: draft.name.trim(), email: draft.email.trim() || null, phone: draft.phone.trim() || null, identityNumber: draft.identityNumber.trim() || null, attributesJson: JSON.stringify(attributes) }); }; const saveCall = () => { if (!clientId || !callDraft.outcome.trim()) return; createCall.mutate({ salesClientId: clientId, callType: callDraft.callType, outcome: callDraft.outcome.trim(), interestLevel: callDraft.interestLevel, interestSubject: callDraft.interestSubject.trim() || null, nextCallAt: callDraft.nextCallAt ? new Date(callDraft.nextCallAt) : null, notes: callDraft.notes.trim() || null }); };
  if (isLoading) return <SalesShell title={t.clientDetails} subtitle={t.loading}><EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /></SalesShell>; if (isError) return <SalesShell title={t.clientDetails} subtitle={t.details} action={<BackToSales />}><SalesQueryFailure retry={refetch} /></SalesShell>; if (!client) return <SalesShell title={t.clientDetails} subtitle={t.details} action={<BackToSales />}><EmptyState message={t.noRecord} icon={<PackageOpen className="mx-auto h-9 w-9 text-[#d8b26b]" />} /></SalesShell>;
  return <SalesShell title={client.name} subtitle={t.clientDetails} action={<><BackToSales /><Button onClick={() => setCallOpen(true)} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]"><PhoneCall className="me-2 h-4 w-4" />{callT.record}</Button>{canManage && <Button onClick={() => editing ? save() : setEditing(true)} disabled={update.isPending} className="bg-white/10 text-white hover:bg-white/15">{update.isPending ? t.loading : editing ? t.save : t.edit}</Button>}</>}><div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><div className="space-y-5"><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader className="flex-row items-center justify-between"><CardTitle>{t.basicInformation}</CardTitle>{logs.length > 0 && <Badge className="border-emerald-300/30 bg-emerald-300/10 text-emerald-100"><CheckCircle2 className="me-1 h-3.5 w-3.5" />{callT.completed}</Badge>}</CardHeader><CardContent className="grid gap-3 pt-0 md:grid-cols-2">{([['name', t.client], ['email', 'Email'], ['phone', 'Phone'], ['identityNumber', 'ID']] as const).map(([key, label]) => <label key={key} className="block"><span className="mb-1 block text-xs text-white/45">{label}</span>{editing && canManage ? <input className={inputClass} value={draft[key] || ""} onChange={event => setDraft(current => ({ ...current, [key]: event.target.value }))} /> : <p className="min-h-10 rounded-xl border border-white/8 bg-black/10 px-3 py-2.5 text-sm text-white/85">{client[key] || "—"}</p>}</label>)}{editing && canManage && <Button type="button" variant="outline" onClick={() => setEditing(false)} className="self-end border-white/15 text-white hover:bg-white/10">{t.cancel}</Button>}</CardContent></Card><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle>{t.imported}</CardTitle><p className="text-sm font-normal text-white/50">{t.allImported}</p></CardHeader><CardContent className="pt-0"><ImportedFields values={attributes} editable={editing && canManage} onChange={(key, value) => setAttributes(current => ({ ...current, [key]: value }))} /></CardContent></Card><Card className="border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle>{callT.history}</CardTitle></CardHeader><CardContent className="space-y-3 pt-0">{inventory.isLoading ? <p className="text-sm text-white/45">{t.loading}</p> : !logs.length ? <p className="text-sm text-white/45">{callT.noHistory}</p> : logs.map((log: any) => <div key={log.id} className="rounded-xl border border-white/10 bg-black/10 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><span className="font-medium text-white">{log.callType}</span><Badge className="border-emerald-300/30 bg-emerald-300/10 text-emerald-100"><CheckCircle2 className="me-1 h-3.5 w-3.5" />{callT.completed}</Badge></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-white/80">{log.outcome}</p>{log.interestSubject && <p className="mt-2 text-sm text-[#e9cc87]">{log.interestSubject}</p>}<div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-xs text-white/45"><span>{new Date(log.completedAt).toLocaleString()}</span>{log.nextCallAt && <span>{callT.next}: {new Date(log.nextCallAt).toLocaleString()}</span>}</div></div>)}</CardContent></Card></div><Card className="h-fit border-white/10 bg-white/[.035] text-white"><CardHeader><CardTitle>{t.linkedContracts}</CardTitle></CardHeader><CardContent className="pt-0">{contracts.length ? <div className="space-y-2">{contracts.map((contract: any) => <button key={contract.id} onClick={() => navigate(`/sales/contracts#contract-${contract.id}`)} className="flex w-full items-center justify-between rounded-xl border border-white/10 bg-black/10 px-3 py-3 text-start hover:bg-white/[.06]"><span><strong>{contract.contractNumber}</strong><small className="ms-2 text-white/45">{contract.status}</small></span><span className="text-[#e9cc87]">{money(contract.netPriceIls)}</span></button>)}</div> : <p className="text-sm text-white/45">—</p>}</CardContent></Card></div><Dialog open={callOpen} onOpenChange={setCallOpen}><DialogContent className="border-white/15 bg-[#0b2031] text-white sm:max-w-xl"><DialogHeader><DialogTitle>{callT.title}</DialogTitle><DialogDescription className="text-white/60">{callT.description}</DialogDescription></DialogHeader><div className="grid gap-3"><label><span className="mb-1 block text-xs text-white/55">{callT.callType}</span><select className={inputClass} value={callDraft.callType} onChange={event => setCallDraft(current => ({ ...current, callType: event.target.value as typeof current.callType }))}><option value="outbound">{callT.outbound}</option><option value="inbound">{callT.inbound}</option><option value="meeting">{callT.meeting}</option><option value="whatsapp">{callT.whatsapp}</option><option value="other">{callT.other}</option></select></label><label><span className="mb-1 block text-xs text-white/55">{callT.outcome}</span><textarea className={inputClass} rows={4} value={callDraft.outcome} onChange={event => setCallDraft(current => ({ ...current, outcome: event.target.value }))} /></label><div className="grid gap-3 sm:grid-cols-2"><label><span className="mb-1 block text-xs text-white/55">{callT.interest}</span><select className={inputClass} value={callDraft.interestLevel} onChange={event => setCallDraft(current => ({ ...current, interestLevel: event.target.value as typeof current.interestLevel }))}><option value="not_interested">{callT.notInterested}</option><option value="low">{callT.low}</option><option value="medium">{callT.medium}</option><option value="high">{callT.high}</option><option value="very_high">{callT.veryHigh}</option></select></label><label><span className="mb-1 block text-xs text-white/55">{callT.next}</span><input className={inputClass} type="datetime-local" value={callDraft.nextCallAt} onChange={event => setCallDraft(current => ({ ...current, nextCallAt: event.target.value }))} /></label></div><label><span className="mb-1 block text-xs text-white/55">{callT.subject}</span><input className={inputClass} value={callDraft.interestSubject} onChange={event => setCallDraft(current => ({ ...current, interestSubject: event.target.value }))} /></label><label><span className="mb-1 block text-xs text-white/55">{callT.notes}</span><textarea className={inputClass} rows={2} value={callDraft.notes} onChange={event => setCallDraft(current => ({ ...current, notes: event.target.value }))} /></label><Button onClick={saveCall} disabled={createCall.isPending || !callDraft.outcome.trim()} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]">{createCall.isPending ? t.loading : callT.save}</Button></div></DialogContent></Dialog></SalesShell>;
}

export function SalesContracts() {
  const { lang } = useLocale(); const t = salesText[lang]; const [, navigate] = useLocation(); const { data, isLoading, isError, refetch } = useSalesCenter(); const utils = trpc.useUtils(); const [form, setForm] = useState({ propertyId: "", clientId: "", contractNumber: `SALE-${Date.now()}`, price: "", discountKind: "none", discount: "0", deposit: "0", frequency: "quarterly", years: "1", firstDate: "", notes: "" }); const create = trpc.sales.createContract.useMutation({ onSuccess: () => { setForm({ propertyId: "", clientId: "", contractNumber: `SALE-${Date.now()}`, price: "", discountKind: "none", discount: "0", deposit: "0", frequency: "quarterly", years: "1", firstDate: "", notes: "" }); utils.sales.center.invalidate(); } });
  const price = numberValue(form.price); const discountValue = numberValue(form.discount); const discount = form.discountKind === "percentage" ? Math.round(price * Math.min(discountValue, 100) / 100) : form.discountKind === "fixed" ? Math.min(price, discountValue) : 0; const net = price - discount; const deposit = Math.min(net, numberValue(form.deposit)); const balance = net - deposit; const count = balance ? (form.frequency === "quarterly" ? 4 : form.frequency === "semiannual" ? 2 : 1) * Math.max(1, Math.min(5, Number(form.years) || 1)) : 0; const installment = count ? Math.floor(balance / count) : 0;
  const submit = () => { const propertyId = Number(form.propertyId), clientId = Number(form.clientId); if (!propertyId || !clientId || !form.contractNumber.trim() || !price || (balance > 0 && !form.firstDate)) return; create.mutate({ salesPropertyId: propertyId, salesClientId: clientId, contractNumber: form.contractNumber.trim(), listPriceIls: price, discountKind: form.discountKind as "none" | "fixed" | "percentage", discountValue, depositIls: deposit, paymentFrequency: form.frequency as "quarterly" | "semiannual" | "annual", termYears: Math.max(1, Math.min(5, Number(form.years) || 1)), firstInstallmentAt: form.firstDate ? new Date(`${form.firstDate}T00:00:00`) : null, notes: form.notes.trim() || null }); };
  if (isError) return <SalesShell title={t.contracts} subtitle={t.installmentSchedule} action={<BackToSales />}><SalesQueryFailure retry={refetch} /></SalesShell>;
  return <SalesShell title={t.contracts} subtitle={t.installmentSchedule}><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><Card className="h-fit border-[#d8b26b]/25 bg-[#0b2a3a]/55 text-white"><CardHeader><CardTitle>{t.createContract}</CardTitle></CardHeader><CardContent className="grid gap-3 pt-0"><select className={inputClass} value={form.propertyId} onChange={event => { const selected = data.properties.find((item: any) => Number(item.id) === Number(event.target.value)); setForm(current => ({ ...current, propertyId: event.target.value, price: selected?.listPriceIls == null ? current.price : String(selected.listPriceIls) })); }}><option value="">{t.property}</option>{data.properties.filter((item: any) => item.status !== "sold" && item.status !== "inactive").map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select className={inputClass} value={form.clientId} onChange={event => setForm(current => ({ ...current, clientId: event.target.value }))}><option value="">{t.client}</option>{data.clients.map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><input className={inputClass} placeholder={t.contractNo} value={form.contractNumber} onChange={event => setForm(current => ({ ...current, contractNumber: event.target.value }))} /><input className={inputClass} type="number" placeholder={t.price} value={form.price} onChange={event => setForm(current => ({ ...current, price: event.target.value }))} /><div className="grid grid-cols-2 gap-2"><select className={inputClass} value={form.discountKind} onChange={event => setForm(current => ({ ...current, discountKind: event.target.value }))}><option value="none">{t.discount}</option><option value="fixed">EGP</option><option value="percentage">%</option></select><input className={inputClass} type="number" min="0" placeholder={t.discount} value={form.discount} onChange={event => setForm(current => ({ ...current, discount: event.target.value }))} /></div><input className={inputClass} type="number" min="0" placeholder={t.deposit} value={form.deposit} onChange={event => setForm(current => ({ ...current, deposit: event.target.value }))} /><div className="grid grid-cols-2 gap-2"><select className={inputClass} value={form.frequency} onChange={event => setForm(current => ({ ...current, frequency: event.target.value }))}><option value="quarterly">{t.quarterly}</option><option value="semiannual">{t.semiannual}</option><option value="annual">{t.annual}</option></select><select className={inputClass} value={form.years} onChange={event => setForm(current => ({ ...current, years: event.target.value }))}>{[1,2,3,4,5].map(year => <option key={year} value={year}>{year} {t.years}</option>)}</select></div><input className={inputClass} type="date" value={form.firstDate} onChange={event => setForm(current => ({ ...current, firstDate: event.target.value }))} /><textarea className={inputClass} placeholder={t.notes} value={form.notes} onChange={event => setForm(current => ({ ...current, notes: event.target.value }))} /><div className="rounded-xl border border-white/10 bg-black/15 p-3 text-sm"><p className="flex justify-between"><span className="text-white/50">{t.netPrice}</span><strong>{money(net)}</strong></p><p className="mt-2 flex justify-between"><span className="text-white/50">{t.balance}</span><strong>{money(balance)}</strong></p><p className="mt-2 flex justify-between text-[#e9cc87]"><span>{t.installments} ({count})</span><strong>{money(installment)}</strong></p></div><Button onClick={submit} disabled={create.isPending || !data.properties.length || !data.clients.length} className="bg-[#d8b26b] text-[#071a27] hover:bg-[#efcf8d]">{create.isPending ? t.loading : t.createContract}</Button></CardContent></Card><div>{isLoading ? <EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /> : !data.contracts.length ? <EmptyState message={t.noContracts} icon={<ClipboardList className="mx-auto h-9 w-9 text-[#d8b26b]" />} /> : <div className="space-y-4">{data.contracts.map((contract: any) => { const property = data.properties.find((item: any) => Number(item.id) === Number(contract.salesPropertyId)); const client = data.clients.find((item: any) => Number(item.id) === Number(contract.salesClientId)); const installments = data.installments.filter((item: any) => Number(item.salesContractId) === Number(contract.id)); return <Card id={`contract-${contract.id}`} key={contract.id} className="border-white/10 bg-white/[.035] text-white"><CardHeader className="flex-row items-start justify-between gap-3"><div><CardTitle>{contract.contractNumber}</CardTitle><p className="mt-2 text-sm text-white/50">{property?.name || "—"} · {client?.name || "—"}</p></div><Badge className={statusClass(contract.status === "completed" ? "sold" : contract.status === "cancelled" ? "inactive" : contract.status === "draft" ? "reserved" : "available")}>{contract.status}</Badge></CardHeader><CardContent className="pt-0"><div className="grid gap-3 text-sm sm:grid-cols-4"><p><span className="block text-xs text-white/40">{t.price}</span>{money(contract.listPriceIls)}</p><p><span className="block text-xs text-white/40">{t.netPrice}</span>{money(contract.netPriceIls)}</p><p><span className="block text-xs text-white/40">{t.deposit}</span>{money(contract.depositIls)}</p><p><span className="block text-xs text-white/40">{t.balance}</span>{money(contract.balanceIls)}</p></div><div className="mt-5"><p className="text-sm font-medium text-[#e9cc87]">{t.installmentSchedule}</p>{installments.length ? <div className="mt-2 grid gap-2 md:grid-cols-2">{installments.map((item: any) => <div key={item.id} className="flex justify-between rounded-lg border border-white/8 bg-black/10 px-3 py-2 text-sm"><span>#{item.sequenceNumber} · {new Date(item.dueAt).toLocaleDateString()}</span><strong>{money(item.amountIls)}</strong></div>)}</div> : <p className="mt-2 text-sm text-white/45">—</p>}</div></CardContent></Card>; })}</div>}</div></div></SalesShell>;
}

export function SalesImport() {
  const { lang } = useLocale(); const t = salesText[lang]; const { data, isLoading, isError, refetch } = useSalesCenter(); const utils = trpc.useUtils(); const [notice, setNotice] = useState(""); const [error, setError] = useState(""); const [summary, setSummary] = useState<any>(null); const importBatch = trpc.sales.importBatch.useMutation({ onSuccess: result => { setError(""); setNotice(`${t.importSuccess}: ${result.rowCount} ${t.rows}`); setSummary(result.importSummary); utils.sales.center.invalidate(); }, onError: failure => setError(failure.message) }); const remove = trpc.sales.deleteImportBatch.useMutation({ onSuccess: () => { utils.sales.center.invalidate(); setNotice(t.delete); }, onError: failure => setError(failure.message) });
  const { canManage } = useSalesViewer();
  if (!canManage) return <SalesShell title={t.importTitle} subtitle={t.details} action={<BackToSales />}><EmptyState message={t.noRecord} icon={<FileSpreadsheet className="mx-auto h-9 w-9 text-[#d8b26b]" />} /></SalesShell>;
  const upload = async (kind: "properties" | "clients", file?: File) => { if (!file) return; setNotice(""); setError(""); setSummary(null); if (!/\.(xlsx|xls|csv)$/i.test(file.name) || file.size > 8 * 1024 * 1024) { setError(t.support); return; } try { const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",").slice(1).join(",")); reader.onerror = () => reject(new Error("FILE_READ_FAILED")); reader.readAsDataURL(file); }); importBatch.mutate({ kind, fileName: file.name, contentType: file.type || "application/octet-stream", base64Content: base64 }); } catch { setError("FILE_READ_FAILED"); } };
  if (isError) return <SalesShell title={t.importTitle} subtitle={t.importIntro} action={<BackToSales />}><SalesQueryFailure retry={refetch} /></SalesShell>;
  return <SalesShell title={t.importTitle} subtitle={t.importIntro} action={<BackToSales />}>{(notice || error) && <p className={`mb-4 rounded-xl border px-3 py-2 text-sm ${error ? "border-rose-300/25 bg-rose-400/10 text-rose-100" : "border-emerald-300/25 bg-emerald-400/10 text-emerald-100"}`}>{error || notice}</p>}{summary && <Card className="mb-5 border-[#d8b26b]/25 bg-[#d8b26b]/[.07] text-white"><CardContent className="grid gap-4 p-4 md:grid-cols-2"><div><p className="text-xs text-white/45">{t.mapped}</p><p className="mt-1 break-words text-sm">{summary.mappedColumns?.join(" · ") || "—"}</p></div><div><p className="text-xs text-white/45">{t.retained}</p><p className="mt-1 break-words text-sm">{summary.retainedColumns?.join(" · ") || "—"}</p></div></CardContent></Card>}<div className="grid gap-5 xl:grid-cols-[.7fr_1.3fr]"><Card className="h-fit border-[#d8b26b]/25 bg-[#0b2a3a]/55 text-white"><CardHeader><CardTitle>{t.import}</CardTitle></CardHeader><CardContent className="grid gap-3 pt-0"><label className="flex cursor-pointer items-center justify-between gap-3 rounded-xl border border-dashed border-[#d8b26b]/35 bg-black/10 px-3 py-4 text-sm text-white/75"><span>{t.propertyFile}</span><input type="file" accept=".xlsx,.xls,.csv" className="sr-only" disabled={importBatch.isPending} onChange={event => { upload("properties", event.target.files?.[0]); event.currentTarget.value = ""; }} /><FileSpreadsheet className="h-5 w-5 text-[#d8b26b]" /></label><label className="flex cursor-pointer items-center justify-between gap-3 rounded-xl border border-dashed border-[#d8b26b]/35 bg-black/10 px-3 py-4 text-sm text-white/75"><span>{t.clientFile}</span><input type="file" accept=".xlsx,.xls,.csv" className="sr-only" disabled={importBatch.isPending} onChange={event => { upload("clients", event.target.files?.[0]); event.currentTarget.value = ""; }} /><FileSpreadsheet className="h-5 w-5 text-[#d8b26b]" /></label><p className="text-xs leading-5 text-white/45">{t.support}</p></CardContent></Card><div>{isLoading ? <EmptyState message={t.loading} icon={<Loader2 className="mx-auto h-8 w-8 animate-spin text-[#d8b26b]" />} /> : !data.batches.length ? <EmptyState message="—" icon={<FileSpreadsheet className="mx-auto h-9 w-9 text-[#d8b26b]" />} /> : <div className="space-y-3">{data.batches.map((batch: any) => <Card key={batch.id} className="border-white/10 bg-white/[.035] text-white"><CardContent className="flex flex-wrap items-center justify-between gap-4 p-4"><div className="min-w-0"><strong className="block truncate">{batch.fileName}</strong><p className="mt-1 text-sm text-white/50">{batch.kind} · {batch.rowCount} {t.rows}</p></div><div className="flex gap-2"><a href={batch.fileUrl} target="_blank" rel="noreferrer" className="rounded-lg border border-white/15 px-3 py-2 text-sm text-[#e9cc87] hover:bg-white/5">{t.open}</a><Button variant="outline" disabled={remove.isPending} onClick={() => { if (window.confirm(t.delete)) remove.mutate({ batchId: Number(batch.id) }); }} className="border-rose-300/25 text-rose-100 hover:bg-rose-300/10">{t.delete}</Button></div></CardContent></Card>)}</div>}</div></div></SalesShell>;
}
